    throw new CryptoError('Encryption failed', 'INVALID_KEY_SIZE');
  }

  // Validate IV size
  if (iv.length !== AES_IV_SIZE) {
    throw new CryptoError('Encryption failed', 'INVALID_IV_SIZE');
  }

